/// After calling `myfun(a, sum, N)`:
///   • `a.len() == N as usize` still holds, and
///   • every element of `a` is 0,
///   • `sum.len() == 1` still holds, and
///   • `sum[0] == N`.
#[requires(N > 0)]
#[requires(a.len() == N as usize)]
#[requires(sum.len() == 1)]
#[ensures(a.len() == old(a.len()))]           // length of `a` is unchanged
#[ensures(sum.len() == old(sum.len()))]       // length of `sum` is unchanged
#[ensures(forall(|i: usize| i < a.len() ==> a[i] == 0))]
#[ensures(sum[0] == N)]
#[decreases(N)]
pub fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    // Preconditions (runtime checks)
    assert!(N > 0, "N must be positive");
    let n = N as usize;
    assert_eq!(
        a.len(),
        n,
        "Length of `a` must be exactly N (here {}).",
        N
    );
    assert_eq!(
        sum.len(),
        1,
        "Length of the accumulator `sum` must be exactly 1."
    );

    // 1) Initialization pass: set each a[i] = 1
    for i in 0..n {
        a[i] = 1;
    }

    // 2) Accumulation pass: reset sum[0] to 0, then add 1 for each element
    sum[0] = 0;
    for _ in 0..n {
        sum[0] += 1;
    }
    // at this point sum[0] == N

    // 3) Normalization pass: set each a[i] = 0
    for i in 0..n {
        a[i] = 0;
    }
}